mapper.select:
SELECT * FROM ( SELECT TO_CHAR(DPP.OPEN_START_DATE,'YYYY-MM-DD') openStartDate ,TO_CHAR(DPP.OPEN_START_DATE,'YYYY-MM-DD')||'至'||TO_CHAR(DPP.OPEN_END_DATE,'YYYY-MM-DD') openDurationDate ,TO_CHAR(DPP.OPEN_END_DATE,'YYYY-MM-DD') openEndDate ,TO_CHAR(DPP.COLLINGOFF_PERIOD,'YYYY-MM-DD') collingoffPeriod ,TO_CHAR(DPP.OPEN_END_DATE+1,'YYYY-MM-DD') settDate FROM REP_PROD_INFO INFO INNER JOIN DIS_PROD_PLAN DPP ON DPP.PROD_ID = NVL(INFO.P_PROD_ID,INFO.PROD_ID) AND DPP.OPEN_END_DATE > TO_DATE(#{openEndDateStr},'yyyy-MM-dd')
AND DPP.OPEN_END_DATE >= #{setDate}
WHERE INFO.STATUS = 'E' AND INFO.PROD_ID = #{prodId,jdbcType=VARCHAR} ORDER BY DPP.OPERATION_START_DATE ) WHERE ROWNUM = 1

SELECT * FROM ( SELECT TO_CHAR(DPP.OPEN_START_DATE,'YYYY-MM-DD') openStartDate ,TO_CHAR(DPP.OPEN_END_DATE,'YYYY-MM-DD') openEndDate ,TO_CHAR(ROUND(NVL(PRI.UNIT_VALUE,0),4),'FM9999999999999990.0000') unitValue ,TO_CHAR(ROUND(NVL(PRI.UNIT_VALUE_T,0),4),'FM9999999999999990.0000') unitValueT ,TO_CHAR(ROUND(NVL(PRI.UNIT_VALUE,0),4),'FM9999999999999990.0000') redValue ,TO_CHAR(ROUND(NVL(PRI.UNIT_VALUE,0),4),'FM9999999999999990.0000') subValue FROM REP_PROD_INFO INFO INNER JOIN DIS_PROD_PLAN DPP ON DPP.PROD_ID = NVL(INFO.P_PROD_ID,INFO.PROD_ID) AND DPP.OPEN_END_DATE <= TO_DATE(#{openEndDateStr},'yyyy-MM-dd')
AND DPP.OPEN_END_DATE > #{setDate}
INNER JOIN REP_PROD_INDEX PRI ON PRI.PROD_ID =INFO.PROD_ID AND PRI.STATUS = 'E' AND PRI.VALUE_DATE = DPP.OPEN_END_DATE where INFO.STATUS = 'E' AND INFO.PROD_ID = #{prodId,jdbcType=VARCHAR} ORDER BY DPP.OPEN_END_DATE DESC ) WHERE ROWNUM <= 3
